parameters.text:
=Kindly generate a warm and professional welcome email for a new client using the following details:

Full Name: {{ $('Edit Fields1').item.json['Full Name'] }}
Email: {{ $('Edit Fields1').item.json['Email'] }}
Company Name: {{ $('Edit Fields1').item.json['Company name'] }}
Industry: {{ $('Edit Fields1').item.json['Industry'] }}
Services Required: {{ $('Edit Fields1').item.json['Services Required'] }}
Starting Date: {{ $('Edit Fields1').item.json['Starting Date'] }}

The email should:
- Greet them by name and welcome them on behalf of AI Tech
- Mention their company name and the service they have signed up for
- Reference their starting date
- Inform them that they will be receiving a separate Terms & Conditions email which will need to be either signed or replied to in order to confirm their agreement before work begins
- Keep the tone friendly, professional, and concise

Sign off the email with:
Name: Ilyas
Email: sender@example.com
Company: AI Tech

parameters.jsCode:
// Get the raw output text from the AI Agent
const text = $input.first().json.output;

// Normalize escaped newlines just in case
const normalized = text.replace(/\\n/g, '\n');

// Extract subject line - text after "Subject:" until end of that line
const subjectMatch = normalized.match(/Subject:\s*(.+)/i);
const subject = subjectMatch ? subjectMatch[1].trim() : '';

// Extract body - everything after the first blank line following the subject
const bodyMatch = normalized.match(/Subject:.+?\n+(.+[\s\S]*)/i);
const body = bodyMatch ? bodyMatch[1].trim() : normalized;

return [{ json: { subject, body } }];

// output is a plain string from T&C Agent
const raw = $input.first().json.output;

// Extract subject - text after "subject:" until newline
const subjectMatch = raw.match(/subject:\s*(.+?)(?:\\n|\n)/i);
const subject = subjectMatch ? subjectMatch[1].trim() : '';

// Extract body - everything after "body:"
const bodyMatch = raw.match(/body:\s*([\s\S]+)/i);
let body = bodyMatch ? bodyMatch[1].trim() : raw;

// Convert newlines to HTML breaks
body = body.replace(/\\n/g, '<br>').replace(/\n/g, '<br>');

// Signature fields on separate lines
body = body.replace(/(Client Name:)/gi, '<br><br><strong>$1</strong> ___________________________<br>');
body = body.replace(/(Signature:)/gi, '<br><strong>$1</strong> ___________________________<br>');
body = body.replace(/(Company:)\s*_{2,}/gi, '<br><strong>Company:</strong> ___________________________<br>');
body = body.replace(/(Date:)\s*_{2,}/gi, '<br><strong>Date:</strong> ___________________________<br>');

// Owner sign-off on separate lines
body = body.replace(/(Authorized by:)/gi, '<br><br><strong>$1</strong><br>');
body = body.replace(/(ilyasammar980@gmail\.com)/gi, '<br>$1<br>');
body = body.replace(/(AI Tech Team|AI Tech)/gi, '<br>$1<br>');

// Best regards
body = body.replace(/(Best regards,?)/gi, '<br><br><strong>$1</strong><br>');

return [{ json: { subject, body } }];
